namespace Invoicing;

/// <summary>
/// Provides the public billing API and delegates each operation to a focused service.
/// </summary>
public sealed class BillingManager
{
    private readonly BillingServices _services = new();

    public string CreateInvoice(Invoice invoice, Account account) =>
        _services.Invoices.CreateInvoice(invoice, account);

    public bool ValidateInvoice(Invoice invoice) =>
        _services.Invoices.ValidateInvoice(invoice);

    public int IssuedCount => _services.Invoices.IssuedCount;

    public decimal ComputeTax(Invoice invoice, string countryCode) =>
        _services.Taxes.ComputeTax(invoice, countryCode);

    public decimal ResolveRate(string countryCode) =>
        _services.Taxes.ResolveRate(countryCode);

    public decimal NetTotal(Invoice invoice) =>
        _services.Taxes.NetTotal(invoice);

    public string IssueReminder(Invoice invoice, Account account) =>
        _services.Dunning.IssueReminder(invoice, account);

    public int ReminderLevel(Invoice invoice) =>
        _services.Dunning.ReminderLevel(invoice);

    public void Post(Invoice invoice, decimal amount) =>
        _services.Ledger.Post(invoice, amount);

    public decimal Settle(Invoice invoice, decimal payment) =>
        _services.Ledger.Settle(invoice, payment);

    public decimal ApplyLateFees(Invoice invoice, Account account) =>
        _services.Dunning.ApplyLateFees(invoice, account);

    public string Reconcile(Account account) =>
        _services.Ledger.Reconcile(account);

    public decimal Balance => _services.Ledger.Balance;
}

internal sealed class BillingServices
{
    internal InvoiceService Invoices { get; } = new();
    internal TaxService Taxes { get; } = new();
    internal DunningService Dunning { get; } = new();
    internal LedgerService Ledger { get; } = new();
}

internal sealed class InvoiceService
{
    private readonly List<string> _issuedNumbers = new();
    private int _nextSequence = 1;

    internal string CreateInvoice(Invoice invoice, Account account)
    {
        if (string.IsNullOrWhiteSpace(account.Id))
            return "no account";
        if (invoice.Lines.Any(line => string.IsNullOrWhiteSpace(line.Description)))
            return "invalid line";
        if (string.IsNullOrEmpty(invoice.Number))
            invoice.Number = $"INV-{_nextSequence++:D6}";
        if (_issuedNumbers.Contains(invoice.Number))
            return "duplicate";
        if (invoice.Lines.Count == 0)
            return "empty";
        if (account.Kind == AccountKind.Government && string.IsNullOrEmpty(account.BillingAddress))
            return "po required";

        _issuedNumbers.Add(invoice.Number);
        return invoice.Number;
    }

    internal bool ValidateInvoice(Invoice invoice)
    {
        if (string.IsNullOrEmpty(invoice.Number))
            return false;
        if (invoice.Lines.Count == 0)
            return false;

        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount < 0m)
                return false;
            if (line.VatRate < 0m || line.VatRate > 1m)
                return false;
        }

        return true;
    }

    internal int IssuedCount => _issuedNumbers.Count;
}

internal sealed class TaxService
{
    private readonly Dictionary<string, decimal> _vatRates =
        new(StringComparer.OrdinalIgnoreCase)
        {
            ["GB"] = 0.20m,
            ["DE"] = 0.19m,
            ["FR"] = 0.20m,
        };

    private const decimal ReducedRate = 0.05m;

    internal decimal ComputeTax(Invoice invoice, string countryCode)
    {
        decimal tax = 0m;
        var rate = ResolveRate(countryCode);

        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount <= 0m)
                continue;
            if (line.VatRate > 0m)
                tax += line.NetAmount * line.VatRate;
            else if (rate > 0m)
                tax += line.NetAmount * rate;
        }

        return Math.Round(tax, 2);
    }

    internal decimal ResolveRate(string countryCode)
    {
        if (string.IsNullOrEmpty(countryCode))
            return ReducedRate;
        if (_vatRates.TryGetValue(countryCode, out var rate))
            return rate;
        return ReducedRate;
    }

    internal decimal NetTotal(Invoice invoice)
    {
        decimal net = 0m;
        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount > 0m)
                net += line.NetAmount;
        }

        return net;
    }
}

internal sealed class DunningService
{
    private readonly Dictionary<string, int> _reminderCounts = new(StringComparer.Ordinal);

    internal string IssueReminder(Invoice invoice, Account account)
    {
        var count = GetReminderCount(invoice);
        if (count >= 3)
            return "escalate";
        if (account.Kind == AccountKind.Government)
            return "no reminder";

        _reminderCounts[invoice.Number] = count + 1;
        if (count == 0)
            return "first notice";
        if (count == 1)
            return "second notice";
        return "final notice";
    }

    internal int ReminderLevel(Invoice invoice)
    {
        var count = GetReminderCount(invoice);
        return count > 3 ? 3 : count;
    }

    internal decimal ApplyLateFees(Invoice invoice, Account account)
    {
        if (string.IsNullOrEmpty(invoice.Number))
            return 0m;

        var level = GetReminderCount(invoice);
        if (level <= 0)
            return 0m;
        if (account.Kind == AccountKind.Government)
            return 0m;

        decimal fee = 0m;
        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount <= 0m)
                continue;
            fee += line.NetAmount * 0.01m * level;
        }

        if (account.Kind == AccountKind.Business && fee > 100m)
            fee = 100m;
        else if (fee > 50m)
            fee = 50m;

        return Math.Round(fee, 2);
    }

    private int GetReminderCount(Invoice invoice) =>
        _reminderCounts.TryGetValue(invoice.Number, out var count) ? count : 0;
}

internal sealed class LedgerService
{
    private readonly List<string> _entries = new();
    private decimal _balance;

    internal void Post(Invoice invoice, decimal amount)
    {
        if (amount == 0m)
            return;

        if (amount > 0m)
            _entries.Add($"DR {invoice.Number} {amount}");
        else
            _entries.Add($"CR {invoice.Number} {-amount}");

        _balance += amount;
    }

    internal decimal Settle(Invoice invoice, decimal payment)
    {
        if (payment <= 0m)
            return _balance;
        if (string.IsNullOrEmpty(invoice.Number))
            return _balance;

        _entries.Add($"PMT {invoice.Number} {payment}");
        _balance -= payment;
        if (_balance < 0m)
            _balance = 0m;
        return _balance;
    }

    internal string Reconcile(Account account)
    {
        if (string.IsNullOrEmpty(account.Id))
            return "no account";
        if (_entries.Count == 0)
            return "no entries";

        decimal credits = 0m;
        decimal debits = 0m;
        foreach (var entry in _entries)
        {
            if (entry.StartsWith("CR", StringComparison.Ordinal))
                credits += 1m;
            else if (entry.StartsWith("DR", StringComparison.Ordinal))
                debits += 1m;
            else if (entry.StartsWith("PMT", StringComparison.Ordinal))
                credits += 1m;
        }

        if (_balance > 0m && debits > credits)
            return "outstanding";
        if (_balance <= 0m)
            return "settled";
        return "partial";
    }

    internal decimal Balance => _balance;
}
